    pt: {"title": "O bilhete", "cover": "", "teaser": "A chuva baixa.", "start": "s1", "scenes": [{"id": "s1", "body": "A chuva baixa. No bolso, a flor seca continua marcando o nome. Helena não pede outra escolha. Só deixa a última estante acesa, caso você queira voltar sem explicar por quê.", "end": "O bilhete"}]},
    es: {"title": "La nota", "cover": "", "teaser": "La lluvia baja.", "start": "s1", "scenes": [{"id": "s1", "body": "La lluvia baja. En el bolsillo, la flor seca sigue marcando el nombre. Helena no pide otra elección. Solo deja el último estante encendido, por si quieres volver sin explicar por qué.", "end": "La nota"}]},
    en: {"title": "The note", "cover": "", "teaser": "The rain eases.", "start": "s1", "scenes": [{"id": "s1", "body": "The rain eases. In your pocket, the dried flower still marks the name. Helena does not ask for another choice. She only leaves the last shelf lit, in case you want to come back without explaining why.", "end": "The note"}]},
